const GODS_KEY="asteria_gods_edit_v1";
function getGods(){// Canonical nation migration: preserve user-edited content while removing deprecated nations.
const RETIRED_NATIONS=["라비엔 자유도시 연맹", "아르벨 공국", "메르안 수로 연합", "마레시아", "에르세나", "라크테아", "에퀴론", "사르하딘", "네르벨 고원령", "칼드라"];
if(Array.isArray(data.regions)){data.regions=data.regions.filter(r=>!RETIRED_NATIONS.includes(r.name));for(const r of DEFAULT_DATA.regions){if(!data.regions.some(x=>x.name===r.name))data.regions.push(structuredClone(r));}}
if(Array.isArray(data.lore)){data.lore=data.lore.filter(x=>!RETIRED_NATIONS.some(n=>(x.title||'').includes(n)));for(const x of DEFAULT_DATA.lore){if(x.id?.startsWith('confirmed_nov23_')&&!data.lore.some(y=>y.id===x.id))data.lore.push(structuredClone(x));}}
// Always reconcile canonical nation records and detailed entries with saved old versions.
if(Array.isArray(data.regions)){data.regions=data.regions.filter(r=>DEFAULT_DATA.regions.some(z=>z.name===r.name));for(const official of DEFAULT_DATA.regions){const found=data.regions.find(r=>r.name===official.name);if(found)found.detail=official.detail;else data.regions.push(structuredClone(official));}}
if(Array.isArray(data.lore)){data.lore=data.lore.filter(x=>!RETIRED_NATIONS.some(n=>[x.title||'',x.category||''].some(v=>v.includes(n))));for(const official of DEFAULT_DATA.lore){if((official.id||'').startsWith('nation_detail_')||(official.id||'').startsWith('atlas_detail_')){const found=data.lore.find(x=>x.title===official.title);if(found){found.detail=official.detail;found.category=official.category;}else data.lore.push(structuredClone(official));}}}

if(!Array.isArray(data.gods))data.gods=structuredClone(GODS_DATA);
if(!Array.isArray(data.lore))data.lore=[];{const seen=new Set(data.lore.map(x=>x.title));for(const item of DEFAULT_DATA.lore){if(!seen.has(item.title)){data.lore.push(structuredClone(item));seen.add(item.title)}}}return data.gods;}
