const ARCHIVE_PARENT_CANON=[
 {id:'karko_parent_archer',name:'다리온 더스틴',aliases:['카르코의 아버지 (더스틴)','카르코의 아버지'],country:'실바족 왕국'},
 {id:'karko_parent_mage',name:'리에나 더스틴',aliases:['카르코의 어머니 (더스틴)','카르코의 어머니'],country:'실바족 왕국'},
 {id:'sion_parent_edmon',name:'에드몬 라우렌',aliases:[],country:'포르카'},
 {id:'sion_parent_marena',name:'마레나 라우렌',aliases:[],country:'포르카'}
];
