const surviving=[];const usedParent=new Set();const usedOtherId=new Set();
for(const c of data.characters){
 if(!c||!c.id)continue;
 const canon=ARCHIVE_PARENT_CANON.find(p=>p.id===c.id||p.name===(c.name||'').trim()||p.aliases.includes((c.name||'').trim()));
 if(canon){
   const canonical=DEFAULT_DATA.characters.find(x=>x.id===canon.id);
   if(!canonical)continue;
   if(usedParent.has(canon.id)){
     const main=surviving.find(x=>x.id===canon.id);
     if(main&&!main.imageId&&c.imageId) main.imageId=c.imageId;
     continue;
   }
   usedParent.add(canon.id);
   const corrected={...canonical};
   if(c.imageId)corrected.imageId=c.imageId;
   surviving.push(corrected);
 }else if(!usedOtherId.has(c.id)) {surviving.push(c);usedOtherId.add(c.id)}
}
for(const p of ARCHIVE_PARENT_CANON){
 if(!usedParent.has(p.id))surviving.push(structuredClone(DEFAULT_DATA.characters.find(c=>c.id===p.id)));
}
data.characters=surviving;
for(const person of data.characters){
 if(person.name==='루나'||person.name==='녹스'){person.country='';continue}
 const parent=ARCHIVE_PARENT_CANON.find(p=>p.id===person.id);
 if(parent) person.country=parent.country;
}
if(Array.isArray(data.relationshipEdges)){
 for(const edge of data.relationshipEdges){
  if(!edge)continue;
  for(const field of ['from','to','source','target','a','b']){
   if(typeof edge[field]!=='string')continue;
   for(const p of ARCHIVE_PARENT_CANON){if(p.aliases.includes(edge[field]))edge[field]=p.name;}
  }
 }
}

