function notice(s){const n=$('#flash');n.textContent=s;n.classList.remove('hide');clearTimeout(notice.t);notice.t=setTimeout(()=>n.classList.add('hide'),3500)}
function uid(prefix){return prefix+'_'+Date.now()+'_'+Math.random().toString(36).slice(2,7)}
function openDB(){return new Promise((resolve,reject)=>{const req=indexedDB.open('asteria_archive_images_v1',1);req.onupgradeneeded=()=>req.result.createObjectStore('images');req.onsuccess=()=>{db=req.result;resolve()};req.onerror=()=>reject(req.error)})}
function dbPut(key,value){return new Promise((resolve,reject)=>{const tx=db.transaction('images','readwrite');tx.objectStore('images').put(value,key);tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error)})}
function dbGet(key){return new Promise(resolve=>{const r=db.transaction('images').objectStore('images').get(key);r.onsuccess=()=>resolve(r.result||'');r.onerror=()=>resolve('')})}
function dbAll(){return new Promise(resolve=>{const out={};const req=db.transaction('images').objectStore('images').openCursor();req.onsuccess=()=>{const c=req.result;if(c){out[c.key]=c.value;c.continue()}else resolve(out)};req.onerror=()=>resolve(out)})}
async function setImage(file,id){if(!file)return;if(!file.type.startsWith('image/'))return notice('이미지 파일만 업로드할 수 있습니다.');try{const result=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>{const img=new Image();img.onload=()=>{const cvs=document.createElement('canvas');const max=id==='worldmap'?2600:1300;const scale=Math.min(1,max/Math.max(img.width,img.height));cvs.width=Math.round(img.width*scale);cvs.height=Math.round(img.height*scale);cvs.getContext('2d').drawImage(img,0,0,cvs.width,cvs.height);resolve(cvs.toDataURL('image/jpeg',.87))};img.onerror=reject;img.src=reader.result};reader.onerror=reject;reader.readAsDataURL(file)});images[id]=result;await dbPut(id,result);render();notice('이미지를 저장했습니다.')}catch(e){notice('이미지 저장에 실패했습니다. 저장 공간을 확인하세요.')}}
const btn=(label,act,cls='')=>`<button type="button" class="btn ${cls}" data-act="${act}">${label}</button>`;
const RETIRED_NATIONS=["라비엔 자유도시 연맹", "아르벨 공국", "메르안 수로 연합", "마레시아", "에르세나", "라크테아", "에퀴론", "사르하딘", "네르벨 고원령", "칼드라"];
function enforceOfficialNations(){
 if(!Array.isArray(data.regions))data.regions=[];
 data.regions=DEFAULT_DATA.regions.map(r=>{const old=data.regions.find(x=>x.name===r.name);return {...r,notes:r.notes};});
 if(!Array.isArray(data.map?.pins))data.map={...(data.map||{}),pins:[]};
 data.map.pins=data.map.pins.filter(p=>!RETIRED_NATIONS.some(n=>String(p.name||'').includes(n)));
 if(Array.isArray(data.lore))data.lore=data.lore.filter(x=>!RETIRED_NATIONS.some(n=>[x.title||'',x.category||''].some(v=>v.includes(n))));
}
const DEEP_CANON_LORE=[{"id":"canon-deep-20261123-1","category":"마력·질환","title":"카이 아르벨라제 — 선천적 마력맥 폐쇄증","detail":"500년 후 영웅 카이의 질환이다. 태어날 때부터 마력맥이 폐쇄되어 막대한 선천 마력을 정상적으로 순환·운용할 수 없다. 마력의 선천 총량과 안정적으로 사용할 수 있는 마력, 종합 전투력은 별개다. 카이엔 아르벨라제에게 이 질환을 부여하지 않는다."},{"id":"canon-deep-20261123-4","category":"마력·질환","title":"바렌의 무연성 즉발 마법","detail":"바렌 드 프리드리히는 마법 발동 시 술식 연성 과정 자체가 없다. 보이지 않는 연성진이나 초고속 계산이 아니다. 얼음 마법을 공격·방어·이동·감금·봉쇄에 응용하고 검술·속도·판단과 결합한다. 효과 발현, 마력 소모, 환경 및 상성에는 한계가 있다."},{"id":"canon-deep-20261123-5","category":"마력·질환","title":"렌의 수중 호흡·보행과 물 조작","detail":"렌 피츠는 물속에서 숨을 쉬고 바닥을 육지처럼 걸으며 물을 자유롭게 조종한다. 이 능력이 동료에게 자동 적용되거나 수압·수온 등 모든 제약을 없애는 것은 아니다."},{"id":"canon-deep-20261123-6","category":"마력·질환","title":"카엘의 초고온 화염과 절제된 검술","detail":"카엘은 불 속성 마법과 검술을 사용하며 매우 작고 정확한 동작으로 우아하고 냉정하게 싸운다. 불꽃은 순간 차갑다고 착각할 만큼 극도로 뜨거운 열을 발생시키지만 냉기 속성은 아니다. 바렌의 무연성 능력을 카엘에게 적용하지 않는다."},{"id":"canon-deep-20261123-7","category":"인물·관계","title":"루나의 기원·기억·불멸","detail":"루나의 본래 이름은 아엘리아. 주황색 머리카락과 눈을 가진 네코라족이다. 신이 인간을 관찰하려 만든 최초의 인간으로 불로불사를 본래 부여받았으나, 자신이 신과 관계된 존재라는 사실은 모른다. 아리아를 만나기 전 수천 년의 기억은 전혀 없고, 자전적으로 기억하는 삶은 약 500년이다. 아리아의 제자이자 기록자이며 불멸을 거둘 방법을 탐구한다."},{"id":"canon-deep-20261123-8","category":"인물·관계","title":"루나의 도덕적 지향과 에일린에 대한 태도","detail":"루나는 소중한 사람을 잃는 고독을 경험하여 에일린의 상실을 깊이 이해한다. 그러나 에일린이 스스로 선택한 가해 행위는 상실로 정당화하지 않는다. 연구만 하는 인물로 축소하지 않고 일상과 관계, 장난과 설렘도 누리는 인물이다. 아리아를 스승님이라 부르고 존댓말을 쓴다."},{"id":"canon-deep-20261123-9","category":"인물·관계","title":"에일린의 정신 지배와 책임","detail":"에일린은 벨로스에게 오랫동안 정신 지배당했고 당시에는 이를 인식하지 못했다. 녹스 진영을 떠나 카엘에게 향한 후 녹스가 직접 말해 주어 처음 알았다. 그전에는 행동을 전부 자신의 의지로 했다고 믿었다. 지배 기간과 지배 종료 후 자발적 행위의 책임을 구분한다. 모르텐은 이 진상을 악용해 에일린을 괴롭힌다."},{"id":"canon-deep-20261123-10","category":"인물·관계","title":"카이엔과 14세 에일린","detail":"1부에서 14세 에일린은 카이엔을 사랑했고 카이엔은 그 감정을 어렴풋이 알아차렸으나 너무 어리다고 판단하여 연애하지 않았다. 전쟁 중 살아남을지도 불확실해 감정을 모르는 척했으며 장래를 약속하지 않았다."},{"id":"canon-deep-20261123-11","category":"인물·관계","title":"카르코의 전문성과 후일담","detail":"카르코는 12세부터 혼자 모험했고 음식과 장난을 좋아하지만 야외 생존·수로·지형·식량 확보에 능하며 기록 수첩을 쓴다. 전문 영역에서는 단호하고 집중력이 높다. 후대 개정 도감에는 식용·독성·회피법·위험 신호가 수록된다. 미래 연인은 엘리나 베르디스다."},{"id":"canon-deep-20261123-12","category":"인물·관계","title":"카이엔과 바렌, 카엘과 렌의 우정 대비","detail":"카이엔과 바렌은 성향이 달라도 서로 존중하고 운동의 호흡이 잘 맞으며 자연스러운 스킨십이 있다. 카엘과 렌은 취향·생활 방식이 거의 맞지 않지만 대화는 오래 이어지며 이유 없는 신체 접촉에는 서로 불편함을 느낀다."},{"id":"canon-deep-20261123-13","category":"인물·관계","title":"카이와 세라의 감정선","detail":"카이는 새벽등불 치료원에서 세라를 처음 본 순간부터 반했다. 세라의 친절과 세심한 치료가 처음 감정을 더 깊게 한다. 세라는 처음부터 같은 강도로 반하지 않고 상호작용을 통해 천천히 마음을 키운다."},{"id":"canon-deep-20261123-14","category":"인물·관계","title":"아샤의 통치와 부모","detail":"아샤는 실바족 왕국의 공식 국왕이며, 부재 중 동생 아르준은 왕위 계승자가 아닌 국정대리다. 선왕 라젠 베르디아는 국가 재앙 중 모르텐에게 살해되었고 당시 아샤는 현장에 없었다. 원로들의 협조로 신속히 즉위했다. 왕비 미라야 베르디아는 아샤와 이든의 관계에 반대했다."},{"id":"canon-deep-20261123-15","category":"역사·본편","title":"실바족 왕국의 1년 재앙","detail":"세르칸이 일으킨 질병과 기근을 포함한 국가적 재앙은 약 1년 지속되었다. 모르텐은 당시 국왕 라젠 베르디아를 살해했다. 두 간부의 범행을 혼동하지 않는다."},{"id":"canon-deep-20261123-16","category":"역사·본편","title":"아리아의 시간의 탑과 벨로스","detail":"아리아는 약 100년간 시간의 탑 꼭대기에 감금됐다. 그곳은 공간·시간의 흐름이 멈췄지만 아리아의 사고·이동·마법 연구는 가능했고 노화하지 않았다. 벨로스는 재미로 가두려 했고 다른 탑을 마련하기 귀찮아 기존 탑을 이용했으며 시간의 탑인 사실도 잊고 있었다."},{"id":"canon-deep-20261123-17","category":"역사·본편","title":"녹스 진영 전투력 서열","detail":"녹스 > 모르텐 > 벨로스 > 바르가스 > 세르칸 > 에일린 발렌시아 = 네르시아. 에일린과 네르시아는 별개 인물이며 전투력이 같다. 에일린은 과거 녹스 진영에 있었으나 비공식 저택 현재는 녹스 편이 아니다."},{"id":"canon-deep-20261123-18","category":"역사·본편","title":"포르카의 제로와 멸망","detail":"제로는 포르카의 왕녀였으며 멸망 과정에서 국왕인 아버지, 왕비인 어머니, 형제자매가 모두 죽었다. 제로는 이 죽음에 자신이 관여했다는 사실을 짊어지지만 구체적 행위와 강요 여부는 임의로 단정하지 않는다. 녹스·모르텐이 국가 붕괴의 근본 가해자다."},{"id":"canon-deep-20261123-19","category":"역사·본편","title":"1부 장편 구조와 전쟁 시간","detail":"1부 약 55~65화, 7장 구성. 에일린 합류 이후 일상·실종 아동 구조·시간의 탑·전쟁 준비·다중 전선이 이어지고, 합류 5개월 뒤 최종전이 시작돼 약 1개월간 진행된다. 카이엔의 완전 소멸 봉인, 아리아의 죽음, 에일린의 상실로 마무리된다."},{"id":"canon-deep-20261123-20","category":"역사·본편","title":"2부 장편 구조와 결말","detail":"2부 약 85~100화, 10장 구성. 카엘·루나의 출발, 렌·아샤·카이·시온·세라의 합류, 각 간부와의 사건, 시온과 카이의 희생, 에일린의 저항과 죽음, 카엘이 카이엔의 대체자가 아닌 자기 자신으로 녹스를 쓰러뜨리는 결말을 다룬다."},{"id":"canon-deep-20261123-21","category":"역사·본편","title":"루나의 최종 소망","detail":"녹스를 쓰러뜨린 후 신들의 공간에서 루나는 고대 기억을 모두 되찾고, 당장 죽게 해 달라는 것이 아니라 불멸을 거두어 늙고 자연스럽게 죽을 수 있는 유한한 삶을 요청한다. 신들이 수락하는지와 방식은 별도 확정 전까지 정하지 않는다."},{"id":"canon-deep-20261123-22","category":"역사·본편","title":"아샤의 전후 삶","detail":"2부 전쟁 후 아샤는 실바족 왕국의 왕으로 살아가며 전쟁에서 죽은 두 연인을 평생 기억한다. 두 연인의 이름과 사망 경위는 기존에 확정되지 않은 범위를 함부로 만들어 넣지 않는다."},{"id":"canon-deep-20261123-23","category":"신의 저택·정사 구분","title":"신의 저택 사건과 본편 정사 구분","detail":"신의 저택은 비공식적인 신의 공간으로 본편과 달리 신·영웅이 직접 만날 수 있다. 저택의 구체적 하루 체험, 가상 미래, 현대 AU의 사건은 본편 실제 역사로 자동 편입되지 않는다. 사용자 승인된 인물 특성·능력·과거 사실만 선별 반영한다."},{"id":"canon-deep-20261123-24","category":"신의 저택·정사 구분","title":"500년 전후 영웅들의 가상 미래 체험","detail":"저택에서는 500년 전과 500년 후 영웅들이 각자의 시대에서 전쟁 후 하루를 체험하고 다른 세대는 관찰한다. 하루가 끝나면 저택으로 돌아오며 500년의 간격을 무시하고 한 시대에 거주하지 않는다. 불멸의 루나만 자연적으로 시대를 넘어 생존한다."},{"id":"canon-deep-20261123-25","category":"신의 저택·정사 구분","title":"500년 전 영웅 생존 가상 미래","detail":"기르기오는 왕이 되고 엘레네·니카·레반과 부모 산드라·허버트는 왕궁에 살며, 카이엔과 에일린만 고향 사과농장에 남는다. 바렌은 조이가 아닌 왕녀와 정략결혼한다. 카르코는 생태 연구자, 로제는 의사, 아리아는 사랑한 여성과 삶을 보내고, 루나는 불멸을 연구한다. 이는 본편 실제 역사 아닌 대체 미래다."},{"id":"canon-deep-20261123-26","category":"신의 저택·정사 구분","title":"저택의 신과 비공식 사건","detail":"사랑의 신 아이는 태초부터 존재한 강력한 신으로 영웅을 사랑하고 응원한다. 신들은 윈디 외에는 저택에서 거의 등장하지 않으며 태양신을 친근한 안내자로 재해석하지 않는다. 모르텐은 에일린과 과거부터 알고 지낸 사이이며 저택에서 처음 만나는 것처럼 묘사하지 않는다."},{"id":"canon-deep-20261123-27","category":"세계관·제도","title":"모험가 길드 길의 등불과 에드릭 벨몬트","detail":"전 길드장 에드릭 벨몬트는 43세 인간 남성으로 갈색 머리, 얇은 콧수염, 구겨진 정장을 지녔다. 계약 수주는 능숙하지만 무리한 의뢰와 낙관적 재정 계산으로 자금이 고갈되어 길드원 급여를 주지 못했다. 지급을 약속한 뒤 야밤에 도망쳤고 행방불명이다. 방어·지휘 특화 전직 모험가라는 폐기 설정을 적용하지 않는다."},{"id":"canon-deep-20261123-28","category":"세계관·제도","title":"노르벨의 교육과 공공 의료","detail":"노르벨은 7~13세 의무 기초교육과 무료 공립 기초학교 수업료를 운영한다. 공공 의료시설의 기본 치료는 저렴하고 취약계층은 무료이며 일반 의술·약품과 치유 마법을 병행한다. 지역별 접근성 격차는 존재한다."},{"id":"canon-deep-20261123-29","category":"세계관·제도","title":"몬스터 토벌과 재난 대응","detail":"F~D급은 마을 경비·초급 모험가, C~B급은 숙련 파티·지역 토벌대, A급은 전문 토벌대·기사단·군대, S급은 국가 군사 대응·대피, SS급은 국가 비상사태와 국제 협력 검토, 규격 외는 조사·격리 우선. 신고→조사→길드 등록 및 배정→토벌·포획·퇴치→기록·보상 순이며 반드시 살해하지는 않는다."},{"id":"canon-deep-20261123-30","category":"국가·도시","title":"확정 국가·도시 색인","detail":"카르반 수도 아르켄시아, 고향 마을 애플린. 루가르 수도 에르하임, 라우하·발트하임·그라웬. 실바족 왕국 수도 바나리야, 중심도시 아라냐. 아비에른 수도 벨리오스, 세르비안. 엘리베른 수도 엘데리아, 밀로엔·아르베크. 파르디아 도시 연합 벨카리아·마레티아·카르세노·오르벨로·루미에라. 노르벨 수도 에스테른, 니벨른. 포르카 옛 수도 카르모스, 구왕도 포르카. 폐기 국가를 국가 목록에 재등록하지 않는다."},{"id":"canon-deep-20261123-31","category":"경제·사회","title":"경제와 길드 재정 기록의 구분","detail":"경제 설정은 국가별 화폐·교역·농업·광업·수운 등 기존 승인 내용을 유지한다. 길의 등불의 급여 체불과 에드릭의 도주는 확정 사실이다. 금액·환율·담보 조건 등 원문에서 구체적 수치가 확인되지 않은 항목은 사실처럼 임의로 숫자를 부여하지 않는다."}];
const EXPANDED_CANON_LORE=[{"id":"canon-expanded-20261123-001","category":"본편·결말","title":"에일린의 불로 저주와 죽음의 조건","detail":"에일린의 저주는 노화와 노환에 의한 죽음을 막지만 외상 등 치명상에 의한 사망은 막지 못한다. 카이엔을 되살리려다 녹스를 깨운 뒤 지배·기만을 겪었다. 녹스에게 속은 피해 사실과, 정신 지배에서 벗어난 뒤 자유의지로 저지른 행위의 책임은 구분한다."},{"id":"canon-expanded-20261123-002","category":"본편·결말","title":"에일린의 마지막 방어전","detail":"녹스와의 최종 결전 전에 벌어진 사건. 에일린이 적의 대규모 공격 계획을 알리고 일행이 이를 저지하자 녹스가 도시를 습격한다. 에일린은 높은 지형에서 궁술과 보조 마법으로 피난로를 지키며 시민 대피 시간을 벌고 녹스에게 작은 상처를 남긴다. 카엘은 다른 전선의 시민 구조 후 도착하며, 에일린은 카엘의 품에서 '나…… 조금 더 살고 싶었는데.'라고 말하고 사망한다. 에일린은 최종 결전에 참석하지 않는다."},{"id":"canon-expanded-20261123-003","category":"본편·결말","title":"시온과 카이의 희생 시점","detail":"시온은 최종 결전 이전 바르가스와의 싸움에서 아샤를 지키고 사망한다. 카이는 선천성 마력맥 폐쇄증이 완치되지 않은 상태에서 녹스의 카엘 공격을 막기 위해 자신의 모든 마력을 바쳐 강력한 방어막을 펼치고 사망한다. 방어막은 녹스가 사망한 뒤에도 남는다."},{"id":"canon-expanded-20261123-004","category":"본편·결말","title":"카엘의 귀환과 왕실 장례","detail":"카엘은 전쟁 후 왕궁으로 돌아와 부모 레오나르 국왕·엘리시아 왕비와 동생 카이의 장례를 정식으로 치르고 왕실 가족 공동묘지에 안장한다. 에일린과 시온은 이미 사망했으므로 참석하지 않는다. 카엘은 즉위 후 대신들과 회의하며 국정·재정·군사 행정을 배워 간다."},{"id":"canon-expanded-20261123-005","category":"본편·결말","title":"카엘의 입양 가족","detail":"카엘은 결혼하지 않은 채 카르반의 왕이 되고 오랜 시간이 지난 후 전쟁 고아 리안과 에스텔을 입양한다. 두 아이는 친형제자매가 아니며 카엘은 아이들의 의사를 존중한다. 후대에 입양 자녀 중 한 명이 왕위를 잇는다."},{"id":"canon-expanded-20261123-006","category":"인물·역사","title":"카이엔의 가족과 애플린","detail":"카이엔은 애플린의 사과농장에서 자랐으며 형 기르기오와 조카 니카·레반이 있다. 카이엔은 익은 사과를 고르고 나무를 상하지 않게 따는 법을 안다. 카이엔 사망 후 기존 왕가가 위기에 도망친 상황에서 사람들은 기르기오를 왕으로 추대했다. 카엘과 카이는 카이엔의 직계가 아니라 기르기오의 혈통이다."},{"id":"canon-expanded-20261123-007","category":"인물·역사","title":"카르반 왕조의 성립","detail":"500년 전 전쟁이 끝나고 카이엔이 죽은 뒤, 도망친 기존 왕가 대신 시민들은 영웅의 형 기르기오를 국왕으로 추대했다. 기르기오는 처음에 왕위를 거절했다. 카이엔의 영웅적 명성이 추대의 주요 배경이었다."},{"id":"canon-expanded-20261123-008","category":"인물·역사","title":"바렌과 조이의 비극적 결별","detail":"바렌은 10세부터 동갑인 조이를 사랑했고 15세에 연애했다. 바렌의 아버지는 조이를 투옥해 고문과 멸시를 가했지만 바렌은 당시 몰랐다. 전쟁 후 국가가 프리드리히 공작가를 왕실 편으로 끌어들이기 위해 왕녀 엘레오노라와의 정략결혼을 추진했다. 바렌은 조이와 결혼하고 싶었으나 조이가 울며 왕녀와 결혼해 달라고 부탁하고 떠났다. 조이는 바렌에게 존댓말을 사용한다. 조이는 라우하 출신 이누스족 평민이다. 바렌과 동갑으로 10세에 만나 15세부터 연애했고 서로 존댓말을 썼다. 멜킨의 이간질과 가문의 반대, 부친의 투옥·고문 및 왕실의 정략혼 압력으로 고통받았다. 바렌은 당시 고문 사실을 몰랐다. 18세 전쟁 후 청혼을 거절하고 영원한 작별을 고한 뒤 라우하의 가족에게 돌아가서야 임신을 알았다. 19세 아들 노먼 피츠를 낳았다. 아버지 없는 아이로 키우고 싶지 않아 피츠라는 성을 지었다. 바렌은 임신과 아들의 존재를 평생 몰랐다. 조이는 재봉사로 일하며 가족의 도움으로 아들을 키우고 평생 미혼으로 살았다. 바렌의 결혼, 자녀 탄생, 공적, 중년 초상, 은퇴, 부고 등 수십 년간 신문으로 그의 소식을 접하고 기사를 모았다. 77세에 바렌의 회고록을 읽고 노먼에게 건넸다. 손주 세 명과 가족을 두고 82세에 노환으로 사망하여 라우하 가족 묘지에 안장됐다."},{"id":"canon-expanded-20261123-009","category":"인물·역사","title":"조이의 라우하 정착과 렌의 혈통","detail":"조이는 라우하 출신 이누스족 평민이다. 바렌과 동갑으로 10세에 만나 15세부터 연애했고 서로 존댓말을 썼다. 멜킨의 이간질과 가문의 반대, 부친의 투옥·고문 및 왕실의 정략혼 압력으로 고통받았다. 바렌은 당시 고문 사실을 몰랐다. 18세 전쟁 후 청혼을 거절하고 영원한 작별을 고한 뒤 라우하의 가족에게 돌아가서야 임신을 알았다. 19세 아들 노먼 피츠를 낳았다. 아버지 없는 아이로 키우고 싶지 않아 피츠라는 성을 지었다. 바렌은 임신과 아들의 존재를 평생 몰랐다. 조이는 재봉사로 일하며 가족의 도움으로 아들을 키우고 평생 미혼으로 살았다. 바렌의 결혼, 자녀 탄생, 공적, 중년 초상, 은퇴, 부고 등 수십 년간 신문으로 그의 소식을 접하고 기사를 모았다. 77세에 바렌의 회고록을 읽고 노먼에게 건넸다. 손주 세 명과 가족을 두고 82세에 노환으로 사망하여 라우하 가족 묘지에 안장됐다. 렌은 바렌 드 프리드리히와 조이 콜린스의 아들 노먼 피츠의 직계 후손이다. 혈통은 여러 세대를 거치며 잊혔고 렌과 루나는 처음에는 모른다. 본편 2부 중후반에 반환 편지, 조이의 일기, 콜린스 가족 기록장, 라우하 출생·가족 문서 및 외부 보존 사본을 대조해 확인한다. 지아와 오르빈이 일부 단서를 발견하고 루나와 렌이 나머지를 확인한다. 렌과 루나는 라우하 가족 묘지에서 조이와 노먼을 추모한다. 렌은 피츠 성씨와 기존 정체성을 유지하며 귀족 지위·재산을 요구하지 않는다. 바렌과 미묘한 얼굴 윤곽·손·집중 표정의 유사성, 조이의 눈매가 남지만 기존 외모는 유지한다. 능력은 혈통만으로 설명하지 않는다."},{"id":"canon-expanded-20261123-010","category":"인물·역사","title":"렌의 부모와 토끼 인형","detail":"렌의 아버지는 렌이 태어나기 몇 달 전 어선 침몰로 죽었으며, 나중에 블라이드족 귀족이 어선을 격침한 사건으로 밝혀진다. 렌은 아버지를 만난 적이 없다. 어머니는 렌이 다섯 살 때 라우하 습격으로 죽었다. 렌은 어머니가 준 낡은 토끼 인형을 간직하며, 어머니는 아들의 생사를 몰라 저승과 이승 사이 갈대밭에서 강을 건너지 않고 머문다."},{"id":"canon-expanded-20261123-011","category":"인물·역사","title":"렌의 절약과 문자 생활","detail":"렌은 어린 시절 빈곤과 노숙을 겪어 숙박비와 식비를 아끼고 저렴한 여관을 찾는 데 능하다. 렌은 글을 읽지 못한다. 카르코의 기록을 계승한 도감의 그림을 보거나 동료에게 설명을 들어 야생 식량과 위험 생물을 구별한다."},{"id":"canon-expanded-20261123-012","category":"인물·역사","title":"시온과 세라의 어린 시절","detail":"시온은 태어날 때부터 귀신과 악마 등 보이지 않는 존재를 보았고 처음에는 모두가 볼 수 있다고 여겼다. 부모는 이를 두려워해 시온을 버렸다. 세라는 버려지지 않았으나 오빠를 따라 집을 나왔다. 남매는 떠돌다 난민촌의 신전에서 메인 사제의 보호를 받았고, 이것이 시온이 성직자의 길로 들어선 계기다."},{"id":"canon-expanded-20261123-013","category":"인물·역사","title":"아샤·아르준의 3년간 국정 운영","detail":"라젠 사망 뒤 아샤는 충분한 통치 교육 없이 왕위에 올랐고 장례·국정·전염병 복구·어머니 보호를 떠안았다. 남동생 아르준은 3년간 정치·행정·재정·법률·군사·외교를 공부하고 회의에 참관해 실무를 익혔다. 아샤가 녹스 토벌을 위해 떠날 때 왕위를 양도하지 않고 아르준에게 국정 대행을 맡긴다."},{"id":"canon-expanded-20261123-014","category":"인물·역사","title":"아샤와 이든의 사랑과 상실","detail":"아샤는 왕실 마부 이든과 진심으로 사랑하고 교제했으나 왕실이 관계를 허락하지 않았다. 이든은 유배 전 아샤에게 꽃 한 송이를 자주 선물하며 공주가 아닌 한 사람으로 대했다. 이든은 유배된 지 2년 뒤 기근 중 전염병으로 사망하고 화장되어 무덤이 남지 않았다. 아샤는 매년 그의 생일에 화장 장소에 꽃을 놓는다."},{"id":"canon-expanded-20261123-015","category":"인물·역사","title":"라젠·미라야 베르디아","detail":"라젠은 실바족 왕국 선왕으로 사망 당시 49세, 짙은 갈색 머리·녹색 눈·단정한 수염, 식물 성장과 목재 강화 마법 및 방어·지형 운용에 능하다. 모르텐에게 살해되었다. 왕비 미라야는 47세, 검은 머리·호박색 눈, 전통과 의무를 중시하며 독 정화와 약초 효능 강화 마법을 다룬다. 아샤와 이든의 관계를 반대했다."},{"id":"canon-expanded-20261123-016","category":"인물·역사","title":"루비의 죽음과 아리아의 어둠 마법","detail":"루비는 탑에 갇힌 아리아에게 음식과 물품을 가져다주다 발각되어 주민들에게 살해당했다. 녹스의 부하가 배후에 있었다. 아리아는 분노 속에 마법을 연구했고, 본래 속성이 없었지만 루비가 죽은 지 5년 후 어둠의 신에게 어둠 속성과 가호를 받았다. 외부에서 누군가 결계를 부수기를 100년 동안 기다렸다."},{"id":"canon-expanded-20261123-017","category":"인물·역사","title":"아리아의 독학과 교육 철학","detail":"아리아는 고아원에서 자라 16세에 독립했고 낡은 마법 입문서를 구해 독학했다. 촛불 하나를 켜는 마법조차 여러 번 실패한 뒤 성공했다. 루나와 카이를 지도할 때 학생의 마력 흐름과 습관을 관찰하고 원리를 이해시킨 뒤 직접 시도하게 하며 안전과 신체 부담을 중시한다."},{"id":"canon-expanded-20261123-018","category":"인물·역사","title":"카이의 연구형 마법","detail":"카이는 어린 시절 병약해 검술보다 책으로 독학할 수 있는 마법을 좋아했다. 불 마법의 열전달·범위·마력 소모 효율과 흐름을 연구해 공책에 정리한다. 광역 마법에 익숙해 작은 주문에도 마력을 과하게 퍼뜨리는 습관이 있어 아리아에게 집중·안정 운용을 배운다. 갈색 머리를 길게 길러 꽁지머리로 묶는다."},{"id":"canon-expanded-20261123-019","category":"인물·관계","title":"루나·렌의 숨겨진 키스","detail":"렌은 루나를 처음부터 좋아했으나 표현이 서툴렀고 먼저 키스했다. 두 사람이 키스했다는 사실은 다른 동료 누구도 모른다. 렌은 루나가 다치거나 사라지는 것을 두려워하며, 루나도 렌이 곁에 있어 주는 것을 고마워한다."},{"id":"canon-expanded-20261123-020","category":"인물·관계","title":"카이엔과 에일린의 관계","detail":"카이엔이 에일린을 부르는 별명은 '린'이다. 에일린의 카이엔에 대한 사랑과 상실은 벨로스가 만든 감정이 아니다. 500년 후 카엘과의 관계는 카이엔을 대신하는 관계가 아니며, 카엘을 독립된 사람으로 받아들이는 과정과 연결한다."},{"id":"canon-expanded-20261123-021","category":"마법·전투","title":"아리아와 루나의 전투 방식 대비","detail":"아리아는 빈틈없는 정확한 공격 연계와 넓은 방어 마법을 동시에 운용하는 치밀한 마법사다. 루나는 압도적인 마력 총량으로 고화력 마법을 사용하며 공중에 떠오르거나 비행해 유리한 공격 위치를 잡는다. 루나는 지상 이동 속도가 특히 빠른 인물은 아니다. 두 사람의 강점은 서로 다르다."},{"id":"canon-expanded-20261123-022","category":"마법·전투","title":"카르코의 몬스터·식용 생물 기록","detail":"카르코는 몬스터 외형·서식지·행동 습성·위험 신호를 기록했고 식용 식물·버섯·동물의 독성과 식용 여부도 정리했다. 500년 후 연구자들이 이를 보완해 몬스터 도감과 야외 생존 안내서의 기초로 사용한다."},{"id":"canon-expanded-20261123-023","category":"마법·전투","title":"로제의 강한 몸과 섬세한 손","detail":"로제는 치료자이자 주먹과 근접 격투에 능한 전투형 인물이다. 반복된 격투로 아귀힘과 완력이 강하지만 상처와 붕대를 다루는 손놀림은 매우 섬세하다. 눈치가 빨라 인물 사이의 숨겨진 감정과 어색함도 잘 알아챈다."},{"id":"canon-expanded-20261123-024","category":"마법·전투","title":"마력 총량 측정과 전투력의 구별","detail":"《신의 저택》 길드 「길의 등불」 측정에서 13인 마력 총량 등급은 카이엔 C, 바렌 A, 카르코 A, 로제 B, 시온 A, 아샤 A, 에일린 B, 카엘 A, 렌 B, 세라 B, 루나 SS, 아리아 SS, 카이 SS이다. 카이의 측정 직후 수정구가 깨진다. 등급은 보유 마력 총량만 나타내며 실제 전투력이나 모험가 등급과 다르다. 해당 측정 사건은 비공식 저택 상황극이다."},{"id":"canon-expanded-20261123-025","category":"신·신화","title":"신들의 등급과 혈통","detail":"태양신·사랑의 신은 S급, 금속의 신·신령한 빛의 신·어둠의 신 에레보스·물의 신은 A급, 바람의 신·달빛의 신·불의 신 하리·자연의 신은 B급이다. 물의 신과 자연의 신의 딸은 바람의 신이며, 사랑의 신과 달빛의 신의 자녀는 신령한 빛의 신이다. 신의 등급은 부모 등급을 그대로 계승하지 않는다."},{"id":"canon-expanded-20261123-026","category":"신·신화","title":"루나와 고대 엘루시아","detail":"루나는 태양신이 만든 최초의 인간이다. 고대 네코라족 국가 엘루시아의 수도 세레니온에서 신들과 소통하고 신탁을 전했다. 신의 뜻이 왕권보다 우선하던 국가에서 국왕은 처음에는 루나를 경계하지 않았으나, 사람들이 루나를 신성시할수록 왕권 위협으로 인식했다. 세계 재창조를 거부한 루나는 신들이 기억을 지우는 과정에서 신들에 대한 기억까지 잃고 봉인되었다."},{"id":"canon-expanded-20261123-027","category":"신·신화","title":"망자의 강과 기억","detail":"저승과 이승의 중간에는 갈대밭과 강이 있다. 망자는 강을 건널 때 강물을 마셔 모든 기억을 잊어야 하며, 강을 건넌 뒤 천국 또는 지옥으로 향하고 환생 또는 소멸을 선택할 수 있다. 세부 심판 절차는 별도로 고정하지 않는다."},{"id":"canon-expanded-20261123-028","category":"역사·국가","title":"니벨른의 환각과 중앙정부 조사","detail":"노르벨의 니벨른은 실제 주민과 건물이 있는 현실의 도시이며 녹스 측이 주민의 감각과 기억을 조작한다. 주민들은 조작을 알아차리지 못한다. 도시 내부에 아리아가 갇힌 시간의 탑이 있다. 중앙정부는 행정 기록과 외부 자료의 불일치, 방문객 증언 차이를 발견해 조사관을 보냈지만 원인을 밝혀내지 못했다."},{"id":"canon-expanded-20261123-029","category":"역사·국가","title":"포르카의 왕실 일곱 남매","detail":"포르카 멸망 당시 일곱 남매는 아델하르트(29·남·외교정치), 카산드라(27·여·검술), 에드리안(24·남·학문마법), 제로(19·여·공감), 리아나(18·여·음악예술), 테오도르(16·남·의학치유), 엘리제(12·여·언어기억력)이다. 제로는 멸망 과정에서 부모와 형제자매 모두의 죽음에 관여한 사실을 짊어지며, 19세에 모르텐에게 두 눈을 잃고 악마가 되었다. 구체적 강요·선택 경위는 임의로 단정하지 않는다."},{"id":"canon-expanded-20261123-030","category":"역사·국가","title":"포르카의 국가 형성과 쇠락","detail":"포르카는 산악 공동체들이 자발적으로 통합한 국가로, 각 공동체의 자치권을 보장했다. 장로회 의장은 내부 투표로 선출되며 임기는 3년이다. 한때 아스테리아 국력 3위였지만 녹스와 모르텐의 약 15년간 붕괴 공작으로 최하위까지 추락한 뒤 멸망했다. 멸망은 몬스터 습격이 근본 원인이 아니다."},{"id":"canon-expanded-20261123-031","category":"역사·국가","title":"포르카의 주요 도시와 산업","detail":"포르카의 기존 확정 도시로 아르카디온(수도), 드라베른(광업·석공업), 세리안(농업·목축), 루카벨(교역·교통), 미르카(학문·기록)가 있다. 이후 아카이브 제안에서 '카르모스'를 옛 수도로 확정한 기록도 있으므로, 서로 충돌하는 두 수도 명칭은 동시 확정된 단일 수도라고 단정하지 말고 정합성 검토 대상으로 보존한다."},{"id":"canon-expanded-20261123-032","category":"역사·국가","title":"카르반과 루가르의 지리 관계","detail":"카르반과 루가르는 서로 가장 가까운 이웃 국가로 국경을 접한다. 루가르는 물이 풍부한 나라로 강·호수·해안 생활권이 발달했고 라우하는 수변 지역이다. 루가르의 수도 에르하임, 발트하임 공작가 중심지, 그라웬의 중남부 농업·하천 교역을 함께 기록한다."},{"id":"canon-expanded-20261123-033","category":"경제·생활","title":"국가 경제와 통용 화폐","detail":"아스테리아 각국은 자체 화폐를 사용하며 교역권에서는 금화·은화·동화가 쓰인다. 농업·광업·상업·마법 관련 직업이 경제를 구성한다. 교통은 도보·말·마차·선박이 중심이며 공간 이동은 드물고 어렵다. 국가별 정확한 환율과 이동 시간은 출처에 없는 수치를 임의로 붙이지 않는다."},{"id":"canon-expanded-20261123-034","category":"경제·생활","title":"길의 등불 에드릭의 급여 체불과 도주","detail":"전 길드장 에드릭 벨몬트는 43세 인간 남성으로 갈색 머리·얇은 콧수염·구겨진 정장 차림이다. 말솜씨와 계약 수주 능력은 좋지만 책임감이 부족하다. 무리한 의뢰 수주와 낙관적인 재정 계산으로 자금이 고갈되자 길드원에게 급여를 주지 못했고, 지급을 약속한 뒤 밤에 도망쳤다. 전투·방어·지휘 특화 전직 모험가라는 과거 제안은 폐기한다."},{"id":"canon-expanded-20261123-035","category":"몬스터·사회","title":"위험 등급별 사회 대응","detail":"F~D급은 마을 경비와 초급 모험가, C~B급은 숙련 파티와 지역 토벌대, A급은 전문 토벌대·기사단·군대가 대응한다. S급은 국가 군사 대응과 주민 대피가 필요하고 SS급은 국가 비상사태로 대규모 피난과 국제 협력을 검토한다. 규격 외는 조사·격리를 우선한다."},{"id":"canon-expanded-20261123-036","category":"몬스터·사회","title":"몬스터 의뢰·재난 대응 순서","detail":"일반 토벌 의뢰는 신고→위험 조사→길드 등록·인력 배정→토벌·포획·퇴치→기록·보상 순서다. 반드시 살해할 필요는 없다. S급 이상이 생활권에 접근하면 경보·대피→방어선 구축→구조·치료→복구를 우선한다."},{"id":"canon-expanded-20261123-037","category":"몬스터·사회","title":"국가별 몬스터 피해 환경","detail":"카르반 농경지·숲·산악로, 루가르 광산·산악 마을, 실바족 왕국 밀림·강변, 아비에른 강·호수, 엘리베른 농경지, 파르디아 항구·해역, 포르카 옛 영토 폐허·동굴, 노르벨 설산이 주요 접점이다. 도시·마을 내부는 경비로 상대적으로 안전하고 외곽 도로와 미개척지는 위험이 커진다."},{"id":"canon-expanded-20261123-038","category":"본편·구성","title":"2부의 합류와 분리 순서","detail":"카엘의 2부 여정에서 합류 순서는 렌→아샤→카이→시온·세라이다. 바르가스전 뒤 카엘+렌과 아샤+루나로 나뉘며, 카이는 아샤+루나가 발견한다. 에일린과의 첫 만남은 카엘+렌이 겪는다. 큰 사건은 카르반 습격, 라우하 갈등, 실바 왕국 사건, 포르카 멸망 진상, 간부전, 녹스전, 신들의 공간, 후일담으로 이어진다."},{"id":"canon-expanded-20261123-039","category":"본편·구성","title":"녹스 간부 5명의 역할","detail":"바르가스는 힘과 전쟁을 숭배하는 전사, 세르칸은 질병·생명 변형과 통제에 집착하는 연구자, 벨로스는 기억·감정·자유의지 지배를 추구하는 인물, 네르시아는 녹스를 사랑하며 인정받고 싶어 하고 에일린을 질투한다. 모르텐은 국가·문명 붕괴를 도모하며 인간의 선의와 신뢰를 악용하는 책략가다."},{"id":"canon-expanded-20261123-040","category":"본편·구성","title":"바렌의 과거를 조종한 멜킨과 모르텐","detail":"바렌이 16세에 모험을 떠나도록 아버지의 허락을 유도하고 종족 간 갈등을 거짓말로 악화시킨 실행자는 멜킨이다. 모르텐이 배후에서 멜킨을 조종했다. 이 음모를 벨로스의 짓으로 설명하는 이전 설정은 폐기한다."},{"id":"canon-expanded-20261123-041","category":"집필·정사","title":"신의 저택과 본편의 구별","detail":"《신의 저택》에서 캐릭터가 실제로 만났거나 신의 저택에서 특정 물건·능력·미래를 경험한 사건은 별도 채택 없이는 본편 역사에 발생한 일이 아니다. 본편으로 채택된 과거·능력·감정의 사실과, 이를 드러낸 비공식 에피소드의 사건·정확한 대사를 분리한다."},{"id":"canon-expanded-20261123-042","category":"집필·정사","title":"대화와 호칭의 공식 규칙","detail":"판타지 《신의 저택》에서 바렌은 모든 인물에게 존댓말을 쓰지만 이름 뒤에 '님'은 붙이지 않는다. 루나는 500년 전 인물에게만 존댓말, 500년 후 인물에게 반말한다. 카엘도 500년 전 인물에게 존댓말, 500년 후 인물에게 반말한다. 카이는 형 카엘에게, 세라는 오빠 시온에게 반말하며 카이와 세라도 서로 반말한다. 시온은 동료들에게 반말한다."},{"id":"canon-expanded-20261123-043","category":"집필·정사","title":"현대 AU와 본편 분리","detail":"현대 고등학교 AU·통합 현대 AU 및 그 제1·제2세계관의 진로·결혼·연애·가족 사건은 판타지 본편 캐논으로 자동 편입하지 않는다. 《신의 저택》의 가상 미래 체험 역시 실제 미래 확정이 아니다."}];
for(const entry of EXPANDED_CANON_LORE){const old=data.lore.find(x=>x.id===entry.id);if(old){Object.assign(old,entry)}else{data.lore.push({...entry})}}
for(const entry of DEEP_CANON_LORE){const old=data.lore.find(x=>x.id===entry.id);if(old){Object.assign(old,entry)}else{data.lore.push({...entry})}}
function render(){enforceOfficialNations();ensureAshaParents();enforceRankFields();document.title=data.title+' | 아스테리아';$('#nav').innerHTML=navItems.map(([k,label])=>`<button data-page="${k}" class="${page===k?'active':''}">${label}</button>`).join('');$('#main').innerHTML=({home:renderHome,characters:renderChars,relations:()=>renderRelationshipGraph('relations'),map:renderMap,regions:renderRegionsView,gods:renderGods,monsters:renderMonsters,combat:renderCombat,stories:renderStories,timeline:renderTimeline,guild:renderGuild,lore:renderLore,manage:renderManage})[page]();}
function head(eng,title,desc,actions=''){return `<header class="top"><div><span class="eyebrow">${esc(eng)}</span><h2>${esc(title)}</h2><p>${esc(desc)}</p></div><div class="actions">${actions}</div></header>`}
function section(title,sub=''){return `<div class="section-head"><h3>${esc(title)}</h3><p>${esc(sub)}</p></div>`}
function renderHome(){return `${head('THE CHRONICLES OF ASTERIA','500년의 시간, 하나의 세계','확정된 설정과 앞으로 채워 나갈 이야기를 함께 보관하는 작업 공간') }<div class="hero"><span class="eyebrow">OFFICIAL STORY TITLE</span><h3>${esc(data.title)}</h3><p>5년간 이어진 전쟁과 봉인, 그리고 500년 후 깨어난 마왕. 영웅들의 기록과 후대의 모험을 한곳에서 연결합니다.</p><div class="actions">${btn('인물 도감 보기','go-characters','primary')}${btn('길드 등급표 보기','go-guild')}</div></div><div class="stats"><div class="stat"><strong>${data.characters.length}</strong><span>등록된 인물</span></div><div class="stat"><strong>${data.regions.length}</strong><span>등록된 지역</span></div><div class="stat"><strong>${data.events.length}</strong><span>연대기 사건</span></div><div class="stat"><strong>${data.lore.length}</strong><span>세계관 설정</span></div></div>${section('세계관의 두 시대')}<div class="two"><div class="panel"><span class="kicker">PART I · 500 YEARS AGO</span><h4>마왕 전쟁의 마지막 해</h4><p>5년간 이어진 전쟁의 막바지. 카이엔 일행과 루나·에일린, 전쟁 속에서 이어진 관계와 최종 봉인의 기록.</p>${btn('500년 전 인물 보기','era-past','small')}</div><div class="panel"><span class="kicker">PART II · 500 YEARS LATER</span><h4>새로운 세대의 모험</h4><p>다시 깨어난 녹스. 카엘과 카이, 새로운 동료들. 500년 동안 남겨진 상처와 기록이 현재의 전쟁과 만납니다.</p>${btn('500년 후 인물 보기','era-future','small')}</div></div>${section('작업 원칙')}<div class="hint">확인된 설정을 수록했습니다. 과거 원문의 모순·추측은 정사로 확정하지 않습니다. 실제로 확인되지 않은 개별 항목은 직접 입력할 수 있습니다. 《신의 저택》 길드 등급은 본편과 구별해서 보관합니다. 대륙 지도는 공식 형태가 정해지지 않았으므로 기본 지도를 임의로 만들지 않았습니다.</div>`}
const ASHA_PARENT_PORTRAITS={"asha_parent_father": "assets/images/57607ed77e7f57.webp", "asha_parent_mother": "assets/images/74793336c98d81.webp"};
const EXTRA_ARCHIVE_PORTRAITS={"레오나르 아르벨라제":"data:image/svg+xml;base64,","엘리시아 아르벨라제":"data:image/svg+xml;base64,","에드릭 벨몬트":"data:image/svg+xml;base64,","멜킨 아르베스":"data:image/svg+xml;base64,","토비아스 벨트란":"data:image/svg+xml;base64,","제로 발카르":"data:image/svg+xml;base64,","에드몬 라우렌":"data:image/svg+xml;base64,","마레나 라우렌":"data:image/svg+xml;base64,"};
const ARCHIVE_PORTRAIT_NAME_BY_ID={"extra_30":"아르벨라제 왕","extra_31":"아르벨라제 왕비","extra_32":"지아 길드 이전 길드장"};
const MISSING_PARENT_PORTRAITS={"karko_parent_archer":"assets/images/74242d0b8fc07e.webp","karko_parent_mage":"assets/images/48575e4434ecc2.webp","sion_parent_edmon":"assets/images/1fa0ba297e5a44.webp","sion_parent_marena":"assets/images/b2320e874a950c.webp"};
function portraitFor(c){const image=MISSING_PARENT_PORTRAITS[c.id]||ASHA_PARENT_PORTRAITS[c.id]||images[c.imageId||'']||CONCEPT_PORTRAITS[c.name]||CONCEPT_PORTRAITS[ARCHIVE_PORTRAIT_NAME_BY_ID[c.id]]||CONCEPT_PORTRAITS[(c.name||'').split(' ')[0]]||EXTRA_ARCHIVE_PORTRAITS[c.name];return image?`<img src="${image}" alt="${esc(c.name)} 초상 이미지" loading="lazy">`:esc(c.name.slice(0,1))}
function conceptLabel(c){return ''}
function characterCard(c){const photo=portraitFor(c);return `<article class="char-card" data-character="${esc(c.id)}"><div class="portrait">${photo}</div><div class="char-body">${conceptLabel(c)}<div class="chips"><span class="chip gold">${esc(c.era)}</span>${canDisplayRank(c)&&c.magic?`<span class="chip" title="마력 등급">${esc(c.magic)}</span>`:''}</div><h4>${esc(c.name)}</h4><p>${esc(c.role||'역할 미정')}</p><p class="country-label">${esc(c.country&&c.country!=='국가 미상 / 미선택'?c.country:((c.name==='루나'||c.name==='녹스')?'—':'국가 미상'))}</p></div></article>`}
function renderChars(){if(selected){const c=data.characters.find(c=>c.id===selected);if(c)return renderDetail(c);selected=null}const filtered=data.characters.filter(c=>(eraFilter==='전체'||c.era===eraFilter||c.era==='양 시대')&&[c.name,c.role,c.race,c.country||'',c.history].join(' ').toLowerCase().includes(search.toLowerCase()));return `${head('CHARACTER ENCYCLOPEDIA','인물 도감','사진과 세부 설정을 인물별로 관리합니다.',btn('+ 인물 추가','add-character','primary'))}<div class="tools" style="margin-bottom:18px"><input id="charSearch" class="search" placeholder="이름, 종족, 역할, 설정 검색" value="${esc(search)}"><select id="eraFilter" class="filter">${['전체','500년 전','500년 후','양 시대','500년 후 이전'].map(e=>`<option ${eraFilter===e?'selected':''}>${e}</option>`).join('')}</select></div>${filtered.length?`<div class="character-grid">${filtered.map(characterCard).join('')}</div>`:'<div class="empty-state">검색 조건에 맞는 인물이 없습니다.</div>'}`}
function detailField(label,val){return `<div class="field"><b>${esc(label)}</b><span>${/등급/.test(label)?esc(val||''):txt(val)}</span></div>`}
function renderDetail(c){return `${head('CHARACTER RECORD',c.name,'상세 프로필 · 확인된 외형을 우선 기재했습니다. 비어 있는 항목은 직접 추가할 수 있습니다.',`${btn('← 목록','back-chars')}${btn('이미지 올리기','upload-character')}${btn('프로필 수정','edit-character','primary')}`)}<div class="detail-hero"><div class="portrait">${portraitFor(c)}</div><div class="panel">${conceptLabel(c)}${detailField('시대',c.era)}${detailField('나이',c.age)}${detailField('종족',c.race)}${detailField('국가 · 출신/소속',c.country||((c.name==='루나'||c.name==='녹스')?'—':'국가 미상 / 미선택'))}${detailField('역할',c.role)}${canDisplayRank(c)?detailField('마력 등급',c.magic):''}${canDisplayRank(c)?detailField('모험 등급',c.adventure):''}</div></div><div class="text-areas">${[['전투 방식',c.style],['인물의 역사',c.history],['성격',c.personality],['말투',c.speech],['대표 대사 3가지 (말투 예시 · 정사 속 실제 발언 아님)',c.dialogue],['외형 상세',c.appearance],['가족·혈연·혼인',c.family],['관계',c.relationships],['추가 메모',c.notes]].filter(([k,v])=>k!=='전투 방식'||(v&&v.trim())).map(([k,v])=>`<div class="panel"><h4>${k}</h4><p>${txt(v)}</p></div>`).join('')}</div><div class="section-head">${btn('인물 삭제','delete-character','danger')}</div>`}

