function monsterCard(m){const art=MATCHED_MONSTER_ART[String(m.id)]||MONSTER_FEATURED_ART[m.name]||MONSTER_CONCEPT_ART[String(m.id)];const artType="";return `<article class="monster-card monster-detail-card"><div class="monster-art"><img loading="lazy" decoding="async" src="${art}" alt="${esc(m.name)} 이미지"></div><div class="monster-heading"><span class="monster-no">NO. ${String(m.id).padStart(2,'0')}</span><span class="monster-grade">${esc(m.grade)}${['규격 외','미정'].includes(m.grade)?'':'급'}</span></div><h3>${esc(m.name)}</h3><p class="monster-hab"><b>주요 서식지</b> ${esc(m.habitat)}</p><p><b>특징·능력</b> ${esc(m.trait)}</p><div class="monster-facts"><span><b>크기</b> ${esc(m.size)}</span><span><b>수명</b> ${esc(m.lifespan)}</span><span><b>먹이</b> ${esc(m.food)}</span><span><b>활동·습성</b> ${esc(m.behavior)}</span><span><b>번식</b> ${esc(m.reproduction)}</span><span><b>약점·대응 취약점</b> ${esc(m.weakness)}</span><span><b>채집 소재</b> ${esc(m.material)}</span><span><b>식용</b> ${esc(m.edible)}</span><span><b>인간과의 관계</b> ${esc(m.human)}</span><span><b>대응·회피법</b> ${esc(m.response)}</span></div></article>`}
function renderMonsters(){const filtered=MONSTER_DETAILS.filter(m=>(monsterGrade==='전체'||m.grade===monsterGrade)&&(monsterHabitat==='전체'||m.habitat.includes(monsterHabitat))&&(!monsterQuery||(Object.values(m).join(' ')).toLowerCase().includes(monsterQuery.toLowerCase())));return `${head('BESTIARY · 80 SPECIES','몬스터 도감','공식 80종 · 상세 생태, 먹이, 번식, 소재, 인간과의 관계, 회피 요령까지 수록. 수명·크기 등은 대표적인 관찰 추정치입니다.')}<div class="tools monster-tools"><input id="monsterSearch" placeholder="이름·능력·서식지·생태 검색" value="${esc(monsterQuery)}"><select id="monsterGrade">${['전체','F','D','C','B','A','S','SS','규격 외','미정'].map(v=>`<option ${monsterGrade===v?'selected':''}>${v}</option>`).join('')}</select><select id="monsterHabitat">${['전체','카르반','루가르','실바','아비에른','엘리베른','파르디아','포르카','노르벨','화산','사막','특수'].map(v=>`<option ${monsterHabitat===v?'selected':''}>${v}</option>`).join('')}</select><span class="minor">${filtered.length} / 80종</span></div><div class="monster-grid">${filtered.map(monsterCard).join('')}</div>${section('위험도별 대응')}<div class="panel"><p>F~D: 마을 경비·초급 모험가　/　C~B: 숙련 파티·지역 토벌대　/　A: 전문 토벌대·기사단·군대　/　S: 국가 군사 대응·대피　/　SS: 국가 비상사태·대규모 피난　/　규격 외: 조사·격리 우선</p><p class="minor">신고 → 위험 조사 → 길드 등록·인력 배정 → 토벌·포획·퇴치 → 기록·보상. 살해는 필수 아님.</p></div>`}
/* old monster renderer retained below */ function oldRenderMonsters(){const known=data.lore.filter(x=>/몬스터|마물|괴물/.test(x.title));return `${head('BESTIARY','몬스터 도감','공식 자료에서 확인된 정보만 표시합니다. 종족·습성·약점이 확인되지 않은 몬스터를 임의로 만들지 않습니다.',btn('+ 몬스터 설정 추가','add-lore','primary'))}<div class="panel"><h3>검증 상태</h3><p>현재 통합 백업에는 이름과 생태·전투법이 모두 확인된 개별 몬스터 종의 목록이 없습니다. 아래는 몬스터에 관해 실제로 기록된 제도와 설정입니다. 새 몬스터는 설정집에 직접 등록할 수 있습니다.</p></div>${known.map(x=>`<div class="panel"><h4>${esc(x.title)}</h4><p>${esc(x.detail)}</p></div>`).join('')}`}
const OFFICIAL_COMBAT_IDS=new Set(["c1", "c10", "c11", "c12", "c13", "c15", "c16", "c17", "c18", "c19", "c2", "c20", "c3", "c4", "c5", "c6", "c7", "c8", "c9", "c_1795284801229_5nw7u", "c_1795287655006_4gm6a"]);
function renderCombat(){const cs=data.characters.filter(c=>OFFICIAL_COMBAT_IDS.has(c.id)&&c.style&&c.style.trim());return `${head('COMBAT CODEX','전투 방식','확정된 영웅과 악당의 전투 방식만 정리합니다.')}<div class="tools"><input id="combatSearch" class="search" placeholder="인물 이름·전투 방식 검색" value="${esc(combatQuery)}"><span class="minor">전투 방식 기록 ${cs.length}명</span></div><div class="two">${cs.filter(c=>(c.name+' '+c.style).toLowerCase().includes(combatQuery.toLowerCase())).map(c=>`<div class="list-card"><h4>${esc(c.name)}</h4><p>${esc(c.style)}</p><div class="chips">${canDisplayRank(c)&&c.magic?`<span class="chip" title="마력 등급">${esc(c.magic)}</span>`:''}${canDisplayRank(c)&&c.adventure?`<span class="chip" title="모험 등급">${esc(c.adventure)}</span>`:''}</div><button class="btn small" data-character="${esc(c.id)}">인물 상세</button></div>`).join('')}</div>`}
let combatQuery=''; document.addEventListener('input',e=>{if(e.target?.id==='combatSearch'){combatQuery=e.target.value;const p=e.target.selectionStart;render();const q=document.getElementById('combatSearch');if(q){q.focus();q.setSelectionRange(p,p)}}});
const VERIFIED_SOURCE_LORE=[{"id":"source-crosscheck-20261123-001","category":"길드·계약","title":"길의 등불 — 국가 경매와 체불임금","detail":"전 길드장이 국가 채무를 갚지 못해 길드 부동산이 담보로 잡혔고, 도주 후 국가 경매에서 지아가 길드를 인수했다. 직원 체불임금은 국가가 먼저 지급한 뒤 책임자에게 추후 회수한다. 직원들은 저마다의 이유로 남았다. 이는 지아가 인수한 길드의 과거이며 에드릭 벨몬트의 급여 체불·도주 설정과 연결된다."},{"id":"source-crosscheck-20261123-002","category":"길드·계약","title":"길의 등불 — 의뢰 보수의 여섯 단계","detail":"길의 등불 고유 방침: ① 계약 시 성공 조건과 완료 증거 합의 ② 의뢰인이 보수 전액 예치, 운영비와 분리 ③ 임시 등록·위험도·능력 검토 후 수행 ④ 토벌 증표·회수품·도착 확인·지도 등 증명 ⑤ 보고서·증거·필요 시 현장 검증 ⑥ 계약 충족 시 지급. 실패·부분 완료·분쟁도 계약 기준으로 처리한다. 모든 길드에 자동 적용되는 보편 규칙은 아니다."},{"id":"source-crosscheck-20261123-003","category":"길드·계약","title":"길의 등불 — 모험가 등록과 등급","detail":"길드 등록 없이도 모험할 수 있고 신원 미확인자를 곧바로 범죄자로 보지 않는다. 임시 등록·제한적 의뢰를 허용하며 다른 길드 기록, 확인된 모험가의 증언, 소속 확인, 활동 이력을 보증 수단으로 삼는다. 등급은 초급→중급→상급→최상급이고 실전 능력·판단·협력·전문성을 평가한다. 원문에는 정식 허가 요건으로 몬스터 100마리 토벌과 100골드 수수료가 별도로 기재되어 있다."},{"id":"source-crosscheck-20261123-004","category":"길드·계약","title":"길의 등불 — 실종·사고·연락 기록","detail":"귀환 지연, 연락 두절, 실종, 사망 확인을 구분하며 미귀환을 곧바로 사망으로 처리하지 않는다. 연락 확인·수색·유품·미지급 보수·유가족 안내를 맡는다. 의뢰·등록·지도·사고·예치금·대여 장비 기록에 출처와 확인 시점을 남긴다. 경비대는 치안·도시 방어, 길드는 의뢰 중개·탐사·구조·토벌을 맡고 영웅협회는 별개 조직이다."},{"id":"source-crosscheck-20261123-005","category":"길드·계약","title":"길의 등불 — 직원과 협력 인물","detail":"지아(길드장), 로웬(현장 조사·위험 검토), 에린(실무), 마레트(회계·계약), 테오(마법 장비), 에반·미레나·노엘·세린(단골 모험가), 토마스 베른(상인), 리네아(약초상), 엘로디아(의료인), 가렌(장비 상인), 마리안(주민), 이베르트·베르단(영웅협회), 피노(우편 배달원), 셀마(행정), 도란(운송업자). 이들의 소속과 담당을 혼동하지 않는다."},{"id":"source-crosscheck-20261123-006","category":"세계관·생활","title":"신생아 이름과 마법 적성 관습","detail":"신생아 출생 후 약 한 달간 마법 적성을 관찰하고 속성이나 부모의 바람에 따라 이름을 짓는 관습이 널리 있으나 의무는 아니다. 에일린의 이름에는 '사랑스러운 작은 꽃'이라는 뜻이 담겼고 시온·세라의 이름에는 성스러움과 기쁨·선함에 대한 바람이 담겼다."},{"id":"source-crosscheck-20261123-007","category":"세계관·생활","title":"마력 부여 의복과 경제적 격차","detail":"마력 부여 의복은 가볍고 유연한 직물로도 높은 방어 성능을 지닐 수 있다. 바렌의 고급 보호 의복과 렌의 초기에 평범한 옷은 경제적 격차를 드러낸다. 렌은 나중에 루나에게 튼튼한 마력 부여 의복을 선물받는다."},{"id":"source-crosscheck-20261123-008","category":"세계관·생활","title":"마력맥 폐쇄증의 일반 의학적 특징","detail":"마력맥 폐쇄증은 선천 마력을 지닌 사람에게만 나타나는 치명적 희귀 질환이다. 대체로 유아기에 발견되고 마력 통로가 막히며 완치법이 없다. 선천 마력이 강할수록 증상이 심각할 수 있다. 카이와 주치의는 불치 사실을 알고 있으나 카엘 등 주변은 완치됐다고 믿는다. 테오는 성장하며 진상을 이해했다."},{"id":"source-crosscheck-20261123-009","category":"세계관·생활","title":"던전·유적 탐사 분류","detail":"던전은 자연 동굴형, 인공 시설형, 마력 이상형 등으로 구분할 수 있다. 탐사 시 전투뿐 아니라 기록·소유권·철수 판단을 고려한다. 몬스터는 먹이·영역·번식·마력 현상에 따라 이동하며 발견했다고 무조건 죽여야 하는 것은 아니다."},{"id":"source-crosscheck-20261123-010","category":"녹스·간부","title":"칠죄종 모티브와 상징","detail":"녹스=교만·독사, 모르텐=탐욕·독화살개구리, 에일린=색욕(카이엔을 향한 사랑과 상실·갈망의 변질을 상징), 바르가스=분노·사자, 네르시아=질투·여우, 벨로스=나태·나무늘보, 세르칸=폭식·해파리. 모티브는 종족과 실제 생물학적 형태를 자동으로 고정하지 않는다."},{"id":"source-crosscheck-20261123-011","category":"녹스·간부","title":"녹스와 에일린 — 소유욕과 자발적 선택","detail":"녹스는 카이엔 부활 약속으로 에일린을 붙잡았고 애착·질투·소유욕과 통제 욕구를 보였다. 에일린은 오랜 세월 카이엔의 목소리·얼굴·향기를 선명하게 떠올리기 어려워졌으나 사랑은 남았다. 녹스의 원치 않은 입맞춤에 명시적으로 거부하지 못한 것은 동의가 아니다. 에일린이 카엘에게 먼저 자발적으로 입 맞춘 선택과 대비된다."},{"id":"source-crosscheck-20261123-012","category":"녹스·간부","title":"녹스와 에일린 — 마지막 거절과 저항","detail":"에일린이 카엘에게 자발적으로 입 맞춘 후 녹스의 성으로 돌아왔을 때, 녹스의 입맞춤을 처음으로 밀어내며 거절한다. 녹스의 질투는 카이엔과 카엘을 향한다. 관계의 파국은 단 한 번의 거절 때문이 아니라 누적된 의심과 저항, 통제 상실에서 비롯된다. 구체적인 《신의 저택》 장면·대사는 본편 정사로 자동 편입하지 않는다."},{"id":"source-crosscheck-20261123-013","category":"인물·과거","title":"아샤의 즉위와 왕비의 상실 반응","detail":"아샤는 아버지 사망 당시 충분한 통치 교육을 받지 못한 상태였고 장례·재정·군사 위협·전염병 피해 수습·어머니의 보호를 동시에 맡았다. 어머니 미라야는 남편의 죽음을 부정하거나 남편을 찾는 심각한 혼란을 겪었다. 아르준은 3년 동안 공부와 회의 참관으로 실무 능력을 길렀고 아샤가 떠난 뒤 국정을 대행했다."},{"id":"source-crosscheck-20261123-014","category":"인물·과거","title":"카이엔·카엘의 동일 마력 지문과 정체성","detail":"카엘은 카이엔과 마력 지문을 100% 공유하지만 기억·인격·의지·영혼이 다른 독립된 인물이다. 카이엔의 환생이나 영혼 파편, 복제품으로 취급하지 않는다. 마법적 동일성은 정체성의 동일함을 뜻하지 않는다."},{"id":"source-crosscheck-20261123-015","category":"인물·과거","title":"에일린의 강압 피해와 가해 책임의 분리","detail":"녹스는 에일린의 상실과 카이엔 부활 소망을 악용해 오랜 세월 심리적으로 조종했다. 에일린의 첫 성적 관계는 녹스의 강압에 의한 비자발적 성폭력이었으며 사랑이나 동의로 해석하지 않는다. 벨로스의 정신 지배 기간 행동은 자유의지에 따른 것으로 단정하지 않고, 지배 종료 후 자신의 의지로 저지른 모험가 유인·죽음의 책임과 구분한다. 노골적인 폭력 장면은 묘사하지 않는다."}];
